#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class NamelessFortressCapture:MonoBehaviour
{
 string output;int checks;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Begin(){if(!Environment.GetCommandLineArgs().Contains("-nameless-fortress-capture"))return;Application.runInBackground=true;var go=new GameObject("Nameless fortress check");DontDestroyOnLoad(go);go.AddComponent<NamelessFortressCapture>();}
 void Check(bool yes,string message){if(!yes)throw new Exception(message);checks++;}
 IEnumerator Start(){output=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/NamelessFortress"));Directory.CreateDirectory(output);var run=Run();while(true){object next=null;bool more=false;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"checks.txt"),"FAILED "+checks+"\n"+ex);Application.Quit(1);yield break;}if(!more)break;yield return next;}File.WriteAllText(Path.Combine(output,"checks.txt"),checks+" eagle animation and presentation checks passed");Application.Quit(0);}
 IEnumerator Run(){yield return null;Application.runInBackground=true;
 var data=EagleFlight.Animation;Check(data!=null&&data.frames.Length==64,"64 imported frames");Check(Mathf.Abs(EagleFlight.CircuitSeconds-26.88f)<.001f,"native timing");float boundary=0;for(int i=0;i<64;i++){Check(EagleFlight.FrameAt(boundary+.001f)==i,"frame "+i);var f=data.frames[i];Check(f.width>0&&f.height>0&&f.x>=0&&f.y>=0&&f.x+f.width<=data.atlasWidth&&f.y+f.height<=data.atlasHeight,"bounds "+i);boundary+=f.seconds;}
 var previous=EagleFlight.Sample(0);for(int i=1;i<=600;i++){var p=EagleFlight.Sample(i*EagleFlight.CircuitSeconds/600);Check(Vector2.Distance(p.anchor,previous.anchor)<.001f,"continuous orbit "+i);Check(p.anchor.x>=.184f&&p.anchor.x<=.336f&&p.anchor.y>=.918f&&p.anchor.y<=.962f,"above tower "+i);previous=p;}Check(Vector2.Distance(previous.anchor,EagleFlight.Sample(0).anchor)<.00001f,"circuit closure");
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.6f);NamelessFortressUI.Show();yield return null;Canvas.ForceUpdateCanvases();var root=GameObject.Find("Nameless Fortress visit");Check(root.GetComponentsInChildren<RawImage>().All(i=>i.texture!=null),"textures loaded");Check(root.GetComponentInChildren<VultureFlight>()==null,"old mechanical bird absent");foreach(var text in root.GetComponentsInChildren<TMP_Text>())Check(!text.isTextOverflowing,"text fits");var flight=root.GetComponentInChildren<EagleFlight>();var bird=flight.GetComponent<RectTransform>();var before=bird.anchorMin;var uv=bird.GetComponent<RawImage>().uvRect;yield return new WaitForSecondsRealtime(.6f);Check(before!=bird.anchorMin&&uv!=bird.GetComponent<RawImage>().uvRect,"live orbit and playback");int reduced=PlayerPrefs.GetInt("Besieged.ReducedMotion",0);PlayerPrefs.SetInt("Besieged.ReducedMotion",1);yield return null;before=bird.anchorMin;uv=bird.GetComponent<RawImage>().uvRect;yield return new WaitForSecondsRealtime(.5f);Check(before==bird.anchorMin&&uv==bird.GetComponent<RawImage>().uvRect,"reduced motion");PlayerPrefs.SetInt("Besieged.ReducedMotion",reduced);flight.enabled=false;
 foreach(float time in new[]{0f,6.72f,13.44f,20.16f}){flight.Present(time);Check(bird.localScale==Vector3.one&&bird.localRotation==Quaternion.identity,"no artificial flip or bank");yield return Capture("eagle-"+size.x+"-"+time.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture));}
 root.GetComponentsInChildren<Button>().Single().onClick.Invoke();yield return null;Check(GameObject.Find("Nameless Fortress visit")==null,"return closes");}
 Screen.SetResolution(640,360,false);yield return new WaitForSecondsRealtime(.4f);NamelessFortressUI.Show();yield return null;Canvas.ForceUpdateCanvases();var loop=GameObject.Find("Nameless Fortress visit").GetComponentInChildren<EagleFlight>();loop.enabled=false;Directory.CreateDirectory(Path.Combine(output,"EagleLoop"));for(int i=0;i<64;i++){loop.Present(i*.42f+.001f);yield return Capture("EagleLoop/"+i.ToString("D3"));}NamelessFortressUI.Close();
 }
    IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.12f);Canvas.ForceUpdateCanvases();var go=new GameObject("Capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cams=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var prior=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=prior;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cams[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
